{"command":"cat > go.mod <<'EOF'
module reimpl-go-mod-outdated

go 1.21
EOF
cat > main.go <<'EOF'
package main

import (
    "encoding/json"
    "flag"
    "fmt"
    "io"
    "log"
    "os"
    "strings"
    "time"
    "unicode/utf8"
)

type Module struct {
    Path     string     `json:"Path"`
    Version  string     `json:"Version"`
    Time     *time.Time `json:"Time"`
    Update   *Module    `json:"Update"`
    Main     bool       `json:"Main"`
    Indirect bool       `json:"Indirect"`
}

func (m *Module) invalidTimestamp() bool {
    if m.Update == nil || m.Time == nil {
        return false
    }
    // This intentionally mirrors the original behavior for malformed input:
    // an Update object without a Time while the current module has Time panics.
    return m.Update.Time.Before(*m.Time)
}

func main() {
    ci := flag.Bool("ci", false, "Non-zero exit code when at least one outdated dependency was found")
    direct := flag.Bool("direct", false, "List only direct modules")
    style := flag.String("style", "default", "Output style, pass 'markdown' for a Markdown table")
    update := flag.Bool("update", false, "List only modules with updates")
    flag.Parse()

    modules, ok := readModules(os.Stdin)
    if !ok {
        return
    }

    rows := make([]*Module, 0, len(modules))
    outdated := false
    for i := range modules {
        m := &modules[i]
        if m.Main {
            continue
        }
        if *direct && m.Indirect {
            continue
        }
        if *update && m.Update == nil {
            continue
        }
        rows = append(rows, m)
        if m.Update != nil && m.Update.Time != nil {
            outdated = true
        }
    }

    renderTable(os.Stdout, rows, *style)

    if *ci && outdated {
        os.Exit(1)
    }
}

func readModules(r io.Reader) ([]Module, bool) {
    dec := json.NewDecoder(r)
    var modules []Module
    for {
        var m Module
        err := dec.Decode(&m)
        if err == io.EOF {
            return modules, true
        }
        if err != nil {
            log.Println(err)
            return nil, false
        }
        modules = append(modules, m)
    }
}

func renderTable(w io.Writer, modules []*Module, style string) {
    if len(modules) == 0 {
        return
    }

    headers := []string{"MODULE", "VERSION", "NEW VERSION", "DIRECT", "VALID TIMESTAMPS"}
    data := make([][]string, 0, len(modules))
    for _, m := range modules {
        newVersion := ""
        if m.Update != nil {
            newVersion = m.Update.Version
        }
        data = append(data, []string{
            m.Path,
            m.Version,
            newVersion,
            fmt.Sprintf("%t", !m.Indirect),
            fmt.Sprintf("%t", !m.invalidTimestamp()),
        })
    }

    widths := make([]int, len(headers))
    for i, h := range headers {
        widths[i] = displayWidth(h)
    }
    for _, row := range data {
        for i, cell := range row {
            for _, line := range splitCell(cell) {
                if dw := displayWidth(line); dw > widths[i] {
                    widths[i] = dw
                }
            }
        }
    }

    if style == "markdown" {
        printRow(w, headers, widths, true)
        printMarkdownSeparator(w, widths)
        for _, row := range data {
            printDataRow(w, row, widths)
        }
        return
    }

    printBorder(w, widths)
    printRow(w, headers, widths, true)
    printBorder(w, widths)
    for _, row := range data {
        printDataRow(w, row, widths)
    }
    printBorder(w, widths)
}

func splitCell(s string) []string {
    parts := strings.Split(s, "\n")
    if len(parts) == 0 {
        return []string{""}
    }
    return parts
}

func printBorder(w io.Writer, widths []int) {
    var b strings.Builder
    b.WriteByte('+')
    for _, width := range widths {
        b.WriteString(strings.Repeat("-", width+2))
        b.WriteByte('+')
    }
    b.WriteByte('\n')
    io.WriteString(w, b.String())
}

func printMarkdownSeparator(w io.Writer, widths []int) {
    var b strings.Builder
    b.WriteByte('|')
    for _, width := range widths {
        b.WriteString(strings.Repeat("-", width+2))
        b.WriteByte('|')
    }
    b.WriteByte('\n')
    io.WriteString(w, b.String())
}

func printDataRow(w io.Writer, row []string, widths []int) {
    lines := make([][]string, len(row))
    maxLines := 1
    for i, cell := range row {
        lines[i] = splitCell(cell)
        if len(lines[i]) > maxLines {
            maxLines = len(lines[i])
        }
    }
    for lineNo := 0; lineNo < maxLines; lineNo++ {
        cells := make([]string, len(row))
        for i := range row {
            if lineNo < len(lines[i]) {
                cells[i] = lines[i][lineNo]
            } else {
                cells[i] = ""
            }
        }
        printRow(w, cells, widths, false)
    }
}

func printRow(w io.Writer, cells []string, widths []int, center bool) {
    var b strings.Builder
    b.WriteByte('|')
    for i, cell := range cells {
        b.WriteByte(' ')
        if center {
            b.WriteString(centerPad(cell, widths[i]))
        } else {
            b.WriteString(rightPad(cell, widths[i]))
        }
        b.WriteByte(' ')
        b.WriteByte('|')
    }
    b.WriteByte('\n')
    io.WriteString(w, b.String())
}

func rightPad(s string, width int) string {
    pad := width - displayWidth(s)
    if pad < 0 {
        pad = 0
    }
    return s + strings.Repeat(" ", pad)
}

func centerPad(s string, width int) string {
    pad := width - displayWidth(s)
    if pad < 0 {
        pad = 0
    }
    left := pad / 2
    right := pad - left
    return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func displayWidth(s string) int {
    // The original table library measures printable rune width. This compact
    // approximation handles ASCII exactly and common wide runes well enough for
    // terminal tables without external dependencies.
    width := 0
    for _, r := range s {
        switch {
        case r == '\t':
            width += 4
        case r < 0x20 || (r >= 0x7f && r < 0xa0):
            // Non-printing controls are not expected after newline splitting.
        case isWide(r):
            width += 2
        default:
            width++
        }
    }
    if width == 0 && s != "" && !utf8.ValidString(s) {
        return len(s)
    }
    return width
}

func isWide(r rune) bool {
    return (r >= 0x1100 && r <= 0x115f) ||
        (r >= 0x2329 && r <= 0x232a) ||
        (r >= 0x2e80 && r <= 0xa4cf) ||
        (r >= 0xac00 && r <= 0xd7a3) ||
        (r >= 0xf900 && r <= 0xfaff) ||
        (r >= 0xfe10 && r <= 0xfe19) ||
        (r >= 0xfe30 && r <= 0xfe6f) ||
        (r >= 0xff00 && r <= 0xff60) ||
        (r >= 0xffe0 && r <= 0xffe6) ||
        (r >= 0x1f300 && r <= 0x1faff) ||
        (r >= 0x20000 && r <= 0x3fffd)
}
EOF
